{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS_META AS WITH BP_STYLE AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, MAX(NULLIF(UPPER(TRIM(L1_CATEGORY)), \'\')) AS L1_CATEGORY FROM SNITCH_DB.MAPLEMONK.BASE_PRODUCT GROUP BY REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') ), MF_NORMALIZED AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, COALESCE( CASE WHEN MF.CATEGORY IS NOT NULL AND TRIM(MF.CATEGORY) <> \'\' THEN CASE WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'T-SHIRTS\',\'T-SHIRT\',\'T SHIRTS\',\'T SHIRT\',\'TSHIRTS\',\'TSHIRT\',\'ROUND NECK\',\'ROUNDNECK\',\'POLO\',\'POLOS\',\'POLO T-SHIRT\',\'POLO T-SHIRTS\') THEN \'T-SHIRTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'TROUSER\',\'TROUSERS\',\'CHINO\',\'CHINOS\',\'CHINO TROUSER\',\'CHINO TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'JEAN\',\'JEANS\',\'DENIM\',\'DENIMS\',\'DEMIN\',\'DEMINS\') THEN \'JEANS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'JACKET\',\'JACKETS\') THEN \'JACKETS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SWEATER\',\'SWEATERS\') THEN \'SWEATERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'HOODIE\',\'HOODIES\') THEN \'HOODIES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'OVERSHIRT\',\'OVERSHIRTS\',\'OVER SHIRT\',\'OVER SHIRTS\') THEN \'OVERSHIRT\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SHORT\',\'SHORTS\') THEN \'SHORTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SHIRT\',\'SHIRTS\',\'HALF SLEEVE SHIRT\',\'HALF SLEEVE SHIRTS\',\'HALF SLV SHIRT\',\'HALF SLV SHIRTS\',\'FULL SLEEVE SHIRT\',\'FULL SLEEVE SHIRTS\',\'FULL SLV SHIRT\',\'FULL SLV SHIRTS\') THEN \'SHIRTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BLAZER\',\'BLAZERS\',\'SUIT\',\'SUITS\',\'SUITS & BLAZERS\') THEN \'BLAZERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'CARGO\',\'CARGOS\',\'CARGO PANT\',\'CARGO PANTS\') THEN \'CARGO PANTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SWEATSHIRT\',\'SWEATSHIRTS\',\'SWEAT SHIRT\',\'SWEAT SHIRTS\') THEN \'SWEATSHIRTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'COORD\',\'COORDS\',\'CO-ORD\',\'CO-ORDS\',\'CO ORD\',\'CO ORDS\') THEN \'COORDS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'JOGGER\',\'JOGGERS\',\'TRACKPANT\',\'TRACKPANTS\',\'TRACK PANT\',\'TRACK PANTS\',\'JOGGERS & TRACKPANTS\',\'JOGGERS AND TRACKPANTS\') THEN \'JOGGERS & TRACKPANTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BOXER\',\'BOXERS\') THEN \'BOXERS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BAG\',\'BAGS\',\'BACKPACK\',\'BACKPACKS\') THEN \'BAGS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'INNERWEAR\',\'INNER WEAR\',\'BRIEF\',\'BRIEFS\',\'BREIF\',\'BREIFS\',\'TRUNK\',\'TRUNKS\') THEN \'INNERWEAR\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SHOE\',\'SHOES\',\'FOOTWEAR\',\'SNEAKER\',\'SNEAKERS\') THEN \'SHOES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'ACCESSORY\',\'ACCESSORIES\',\'SOCK\',\'SOCKS\',\'CAP\',\'CAPS\') THEN \'ACCESSORIES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'SUNGLASS\',\'SUNGLASSES\',\'GOGGLES\') THEN \'SUNGLASSES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'BELT\',\'BELTS\') THEN \'BELTS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'PERFUME\',\'PERFUMES\',\'FRAGRANCE\',\'FRAGRANCES\') THEN \'PERFUMES\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'PYJAMA\',\'PYJAMAS\',\'PAJAMA\',\'PAJAMAS\') THEN \'PYJAMAS\' WHEN UPPER(TRIM(MF.CATEGORY)) IN (\'LUGGAGE\',\'TROLLY\',\'TROLLIES\',\'TROLLEY\',\'TROLLEYS\',\'SUITCASE\') THEN \'LUGGAGE\' ELSE UPPER(TRIM(MF.CATEGORY)) END END, CASE WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MST|4RN|4LRN|4BRN|4PL|4LPL|4BPL|RN|LRN|BRN|PL|LPL|BPL)\') THEN \'T-SHIRTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4TRU|4BR|TRU|BR)\') THEN \'INNERWEAR\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4LSWT|4BSWT|4SWT|LSWT|BSWT|SWT)\') THEN \'SWEATSHIRTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4SHO|SHO|SH0)\') THEN \'SHOES\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MSR|4MTR|4MCN|4BCN|4TR|4LTR|4BTR|4CH|4LCH|4BCH|LTR|BTR|LCH|BCH|CH|TR)\') THEN \'TROUSERS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MVK|4MSD|4MJN|4BJN|4JE|4LJE|4BJE|JE|LJE|BJE)\') THEN \'JEANS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4LJK|4BJK|4JK|LJK|BJK|JK)\') THEN \'JACKETS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MSW|4LSW|4BSW|4SW|LSW|BSW|SW)\') THEN \'SWEATERS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4LHD|4BHD|4HD|LHD|BHD|HD)\') THEN \'HOODIES\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MOS|4LOS|4BOS|4OS|LOS|BOS|OS)\') THEN \'OVERSHIRT\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MSS|4MSN|4SHS|4LSHS|4BSHS|4SFS|4LSFS|4BSFS|LSHS|BSHS|SHS|LSFS|BSFS|SFS)\') THEN \'SHIRTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4SH|4LSH|4BSH|LSH|BSH|SH)\') THEN \'SHORTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4LBL|4BBL|4BL|LBL|BBL|BL)\') THEN \'BLAZERS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MCG|4LCA|4BCA|4CA|LCA|BCA|CA)\') THEN \'CARGO PANTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MCD|4LCD|4BCD|4CD|LCD|BCD|CD)\') THEN \'COORDS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MTP|4LJO|4BJO|4JO|LJO|BJO|JO)\') THEN \'JOGGERS & TRACKPANTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4BX|BX)\') THEN \'BOXERS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4BG|BG|BP)\') THEN \'BAGS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MCP|4MBD|4AC|AC)\') THEN \'ACCESSORIES\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4SU|SU|SN)\') THEN \'SUNGLASSES\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MBL|4BT|BT)\') THEN \'BELTS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MSFR|4PR|PR)\') THEN \'PERFUMES\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4PY|PY)\') THEN \'PYJAMAS\' WHEN REGEXP_LIKE(REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\'), \'^(4MTL)\') THEN \'LUGGAGE\' ELSE \'OTHERS\' END ) AS CATEGORY, COALESCE( BP.L1_CATEGORY, CASE WHEN UPPER(MF.STYLE) LIKE \'%LUXE%\' OR UPPER(MF.SKU_GROUP) LIKE \'4MLX%\' OR UPPER(MF.SKU_GROUP) LIKE \'4LRN%\' OR UPPER(MF.SKU_GROUP) LIKE \'4LPL%\' THEN \'LUXE\' WHEN UPPER(MF.STYLE) LIKE \'%PLUS%\' OR UPPER(MF.SKU_GROUP) LIKE \'4MBG%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BRN%\' OR UPPER(MF.SKU_GROUP) LIKE \'4BPL%\' THEN \'PLUS\' ELSE \'SNITCH\' END ) AS STYLE, NULLIF(UPPER(TRIM(MF.MATERIAL_NEW)), \'\') AS MATERIAL_NEW, NULLIF(UPPER(TRIM(MF.PRINT_DESIGN_MAPPED)), \'\') AS PRINT_DESIGN_MAPPED, NULLIF(UPPER(TRIM(MF.FIT)), \'\') AS FIT, NULLIF(UPPER(TRIM(MF.COLLAR_NEW)), \'\') AS COLLAR_NEW FROM SNITCH_DB.MAPLEMONK.METAFIELDS_DATA MF LEFT JOIN BP_STYLE BP ON REGEXP_REPLACE(UPPER(TRIM(MF.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = BP.CLEAN_SKU_GROUP ), MF_SCORED AS ( SELECT *, ( IFF(CATEGORY IS NOT NULL AND CATEGORY <> \'OTHERS\', 1, 0) + IFF(STYLE IS NOT NULL AND STYLE <> \'\', 1, 0) + IFF(MATERIAL_NEW IS NOT NULL, 1, 0) + IFF(PRINT_DESIGN_MAPPED IS NOT NULL, 1, 0) + IFF(FIT IS NOT NULL, 1, 0) + IFF(COLLAR_NEW IS NOT NULL, 1, 0) ) AS META_COMPLETENESS_SCORE, ROW_NUMBER() OVER ( PARTITION BY CLEAN_SKU_GROUP ORDER BY ( IFF(CATEGORY IS NOT NULL AND CATEGORY <> \'OTHERS\', 1, 0) + IFF(STYLE IS NOT NULL AND STYLE <> \'\', 1, 0) + IFF(MATERIAL_NEW IS NOT NULL, 1, 0) + IFF(PRINT_DESIGN_MAPPED IS NOT NULL, 1, 0) + IFF(FIT IS NOT NULL, 1, 0) + IFF(COLLAR_NEW IS NOT NULL, 1, 0) ) DESC, CATEGORY ASC, STYLE ASC, MATERIAL_NEW ASC NULLS LAST, PRINT_DESIGN_MAPPED ASC NULLS LAST, FIT ASC NULLS LAST, COLLAR_NEW ASC NULLS LAST ) AS META_ROW_RANK FROM MF_NORMALIZED ), SKU_META AS ( SELECT CLEAN_SKU_GROUP, CATEGORY, COALESCE(STYLE, \'SNITCH\') AS STYLE, CASE WHEN CATEGORY = \'T-SHIRTS\' THEN COALESCE(COLLAR_NEW, \'NA\') WHEN CATEGORY IN (\'SHIRTS\', \'JEANS\', \'TROUSERS\') THEN COALESCE(MATERIAL_NEW, \'NA\') ELSE \'NA\' END AS META1, CASE WHEN CATEGORY IN (\'T-SHIRTS\', \'SHIRTS\', \'JEANS\', \'TROUSERS\') THEN COALESCE(PRINT_DESIGN_MAPPED, \'NA\') ELSE \'NA\' END AS META2, CASE WHEN CATEGORY IN (\'T-SHIRTS\', \'SHIRTS\', \'JEANS\', \'TROUSERS\') THEN COALESCE(FIT, \'NA\') ELSE \'NA\' END AS META3 FROM MF_SCORED WHERE META_ROW_RANK = 1 ), SKU_MRP AS ( SELECT REGEXP_REPLACE(UPPER(TRIM( CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END )), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, MAX(TRY_CAST(MRP AS FLOAT)) AS MRP FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY WHERE TRY_CAST(MRP AS FLOAT) IS NOT NULL AND TRY_CAST(MRP AS FLOAT) > 0 GROUP BY 1 ), SKU_PRICED_META AS ( SELECT M.CATEGORY, M.STYLE, M.META1, M.META2, M.META3, U.MRP FROM SKU_META M INNER JOIN SKU_MRP U ON M.CLEAN_SKU_GROUP = U.CLEAN_SKU_GROUP WHERE M.CATEGORY IS NOT NULL AND UPPER(TRIM(M.CATEGORY)) NOT IN (\'NT\', \'CB\', \'OTHERS\', \'NA\', \'\') ), BUCKETED_PRICES AS ( SELECT CATEGORY, STYLE, META1, META2, META3, CASE WHEN MRP < 999 THEN \'VALUE\' WHEN MRP < 1500 THEN \'MID\' WHEN MRP < 2500 THEN \'PREMIUM\' ELSE \'SUPER_PREMIUM\' END AS PRICE_MAJOR_BAND, CASE WHEN MRP < 999 THEN \'Value\' WHEN MRP < 1500 THEN \'Mid\' WHEN MRP < 2500 THEN \'Premium\' ELSE \'Super Premium\' END AS PRICE_MAJOR_BAND_LABEL, CASE WHEN MRP < 999 THEN FLOOR(MRP / 200) * 200 WHEN MRP < 1500 THEN 999 + FLOOR((MRP - 999) / 200) * 200 WHEN MRP < 2500 THEN 1500 + FLOOR((MRP - 1500) / 200) * 200 ELSE 2500 + FLOOR((MRP - 2500) / 200) * 200 END AS SLAB_MIN_PRICE FROM SKU_PRICED_META ), DISTINCT_BUCKETS AS ( SELECT DISTINCT CATEGORY, STYLE, META1, META2, META3, PRICE_MAJOR_BAND, PRICE_MAJOR_BAND_LABEL, SLAB_MIN_PRICE FROM BUCKETED_PRICES ), GENERATED_SLABS AS ( SELECT CATEGORY, STYLE, META1, META2, META3, PRICE_MAJOR_BAND, PRICE_MAJOR_BAND_LABEL, SLAB_MIN_PRICE, CASE WHEN PRICE_MAJOR_BAND = \'VALUE\' THEN LEAST(SLAB_MIN_PRICE + 199, 998) WHEN PRICE_MAJOR_BAND = \'MID\' THEN LEAST(SLAB_MIN_PRICE + 199, 1499) WHEN PRICE_MAJOR_BAND = \'PREMIUM\' THEN LEAST(SLAB_MIN_PRICE + 199, 2499) WHEN SLAB_MIN_PRICE = MAX(SLAB_MIN_PRICE) OVER ( PARTITION BY CATEGORY, STYLE, META1, META2, META3, PRICE_MAJOR_BAND ) THEN 999999 ELSE SLAB_MIN_PRICE + 199 END AS SLAB_MAX_PRICE, DENSE_RANK() OVER ( PARTITION BY CATEGORY, STYLE, META1, META2, META3 ORDER BY SLAB_MIN_PRICE ASC ) AS SLAB_NUM FROM DISTINCT_BUCKETS ) SELECT CATEGORY, STYLE, META1, META2, META3, CONCAT(\'SLAB_\', SLAB_NUM) AS PRICE_SLAB_CODE, PRICE_MAJOR_BAND, PRICE_MAJOR_BAND_LABEL, CASE WHEN SLAB_MAX_PRICE = 999999 THEN CONCAT(\'₹\', CAST(SLAB_MIN_PRICE AS INT), \'+\') ELSE CONCAT(\'₹\', CAST(SLAB_MIN_PRICE AS INT), \' – ₹\', CAST(SLAB_MAX_PRICE AS INT)) END AS PRICE_RANGE_LABEL, SLAB_MIN_PRICE, SLAB_MAX_PRICE, CURRENT_TIMESTAMP() AS CREATED_AT FROM GENERATED_SLABS WHERE UPPER(TRIM(CATEGORY)) NOT IN (\'NT\', \'CB\', \'OTHERS\', \'NA\', \'\') QUALIFY ROW_NUMBER() OVER ( PARTITION BY CATEGORY, STYLE, META1, META2, META3, SLAB_MIN_PRICE ORDER BY SLAB_NUM ASC ) = 1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            